CREATE OR REPLACE FUNCTION public.store_holding(p_world uuid, p_uid uuid, p_defs text[], p_x double precision, p_y double precision)
 RETURNS TABLE(kind text, sid bigint, x integer, y integer, cx double precision, cy double precision)
 LANGUAGE sql
 STABLE
AS $function$
  select s.kind, s.sid, s.x, s.y, s.cx, s.cy from deed_store_items(p_world, p_uid) s
  where (s.it).def = any(p_defs) and (s.it).count > 0 and not coalesce((s.it).locked, false) and store_reached(p_world, s.kind, s.sid)
  order by (s.cx - p_x) ^ 2 + (s.cy - p_y) ^ 2, s.sid limit 1
$function$
